#version 450

layout(local_size_x=512) in;

layout(set=0,binding=0) buffer Input { uint data[]; } input_buf;
layout(set=0,binding=1) buffer Output { uint data[]; } output_buf;
layout(set=0,binding=2) buffer GroupSums { uint data[]; } group_sums;

layout(push_constant) uniform Push { uint N; uint num_groups; };

shared uint sdata[512];

void main() {
    uint idx = gl_GlobalInvocationID.x;
    uint local_id = gl_LocalInvocationID.x;
    uint gid = gl_WorkGroupID.x;

    uint val = 0;
    if (idx < N) {
        val = input_buf.data[idx];
    }
    sdata[local_id] = val;
    barrier();

    // Parallel inclusive scan in shared memory
    for (uint offset = 1; offset < 512; offset <<= 1) {
        uint t = 0;
        if (local_id >= offset) {
            t = sdata[local_id - offset];
        }
        barrier();
        sdata[local_id] += t;
        barrier();
    }

    // Write inclusive scan to output buffer
    if (idx < N) {
        output_buf.data[idx] = sdata[local_id];
    }

    // Write the inclusive-scan value of the last element of this block as the group's partial sum.
    // In a full block (512 elements), the last element is at local_id 511. In the last (partial)
    // block, the last element is at idx == N - 1.
    if (local_id == 511 || idx == N - 1) {
        group_sums.data[gid] = sdata[local_id];
    }
}
