# K3: Add the group's prefix (sum of all elements in previous blocks) to each element.
cat > shaders/add_prefix.glsl <<'EOF'
#version 450

layout(local_size_x=512) in;

layout(set=0,binding=0) buffer Input { uint data[]; } input_buf;
layout(set=0,binding=1) buffer Output { uint data[]; } output_buf;
layout(set=0,binding=2) buffer GroupSums { uint data[]; } group_sums;

layout(push_constant) uniform Push { uint N; uint num_groups; };

void main() {
    uint idx = gl_GlobalInvocationID.x;
    if (idx >= N) {
        return;
    }
    uint gid = idx / 512;
    uint gp = 0;
    // The group prefix for block 'gid' is the group_scan value of block 'gid - 1'.
    // Block 0 has no preceding block, so its prefix is 0.
    if (gid > 0) {
        gp = group_sums.data[gid - 1];
    }
    // Output[idx] currently holds the *inclusive* scan of the block. We convert to exclusive:
    // exclusive_scan[idx] = inclusive_scan[idx] - input[idx] + group_prefix.
    uint inclusive = output_buf.data[idx];
    uint original = input_buf.data[idx];
    output_buf.data[idx] = gp + inclusive - original;
}
EOF

